commit 645d651e83dcd1b8f25e9586e9f53270fd9ede60
Author: Martijn van Beurden <mvanb1@gmail.com>
Date:   Fri Apr 28 19:41:30 2023 +0200

    Only unset 'first' after successful execution

    'first' was handed to flac__encode_file on the first file of a
    set, to let that function know replaygain needs to be initialized.
    However, when processing of the first file fails, the second file
    uses replaygain uninitialized.

diff --git a/src/flac/main.c b/src/flac/main.c
index 3c19f1a9..2bc30355 100644
--- a/src/flac/main.c
+++ b/src/flac/main.c
@@ -543,8 +543,10 @@ int do_it(void)
                        for(i = 0, retval = 0; i < option_values.num_files; i++) {
                                if(0 == strcmp(option_values.filenames[i], "-") && !first)
                                        continue;
-                               retval |= encode_file(option_values.filenames[i], first, i == (option_values.num_files-1));
-                               first = false;
+                               if(encode_file(option_values.filenames[i], first, i == (option_values.num_files-1)))
+                                       retval = 1;
+                               else
+                                       first = false;
                        }
                        if(option_values.replay_gain && retval == 0) {
                                float album_gain, album_peak;
